func:
let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
msg.full_sync_failures = [];
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=full_sync,status=started value=1 ' + nowNs;
return msg;

const found = (msg.payload || '').trim() === 'FOUND';
msg.step1_skipped = !found;
if (found) msg.target = 'GoDaddy Restore from File (Full Sync entry)';
return found ? [msg, null] : [null, msg];

if (!msg.step1_skipped && msg.job_failed) {
    msg.full_sync_failures.push('restore_from_file: ' + (msg.failure_code || 'unknown_error'));
}
delete msg.job_failed;
delete msg.failure_code;
delete msg.failure_detail;
msg.target = 'GoDaddy Pull (Full Sync entry)';
return msg;

if (msg.job_failed) {
    msg.full_sync_failures.push('godaddy_pull: ' + (msg.failure_code || 'unknown_error'));
}
delete msg.job_failed;
delete msg.failure_code;
delete msg.failure_detail;
msg.target = 'wherewhen Data Export (Full Sync entry)';
return msg;

if (msg.job_failed) {
    msg.full_sync_failures.push('wherewhen_export: ' + (msg.failure_code || 'unknown_error'));
}
const failures = msg.full_sync_failures || [];
const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at).getTime();
const status = failures.length ? 'failed' : 'success';

let line = 'sync_job_runs,job_name=full_sync,status=' + status;
if (failures.length) line += ',failure_code=step_failed';
line += ' duration_ms=' + durationMs + ',step1_skipped=' + (msg.step1_skipped ? 'true' : 'false');
if (failures.length) {
    const detail = failures.join('; ').replace(/([ ,="])/g, '\\$1');
    line += ',detail="' + detail + '"';
}
line += ' ' + nowNs;
msg.influx_finish_point = line;

msg.sqlite_job = {
    job_name: 'full_sync',
    mode: failures.length ? 'failure' : 'success',
    last_success: failures.length ? null : new Date().toISOString(),
    last_attempt: new Date().toISOString(),
    last_attempt_ok: failures.length ? 0 : 1,
    last_error: failures.length ? failures.join('; ').slice(0, 250) : null
};

if (failures.length) node.warn('Full Sync completed WITH FAILURES: ' + failures.join('; '));
else node.warn('Full Sync completed successfully' + (msg.step1_skipped ? ' (no import file waiting — restore step skipped)' : '') + '.');
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;

const nowNs = Date.now() * 1000000;
const detail = ((msg.error && msg.error.message) || 'unknown error').toString();
const source = (msg.error && msg.error.source && msg.error.source.name) || 'unknown node';
const safeDetail = (source + ': ' + detail).replace(/([ ,="])/g, '\\$1');
// msg.secrets survives from n_fs_load_secrets unless the failure happened
// before that node ran (e.g. the secrets file itself was unreadable) — in
// that case there's genuinely nothing to log this failure TO, so the next
// node just skips the InfluxDB write and this shows up only in node.warn /
// the Node-RED debug sidebar.
msg.influx_finish_point = 'sync_job_runs,job_name=full_sync,status=failed,failure_code=flow_error detail="' + safeDetail + '" ' + nowNs;
msg.sqlite_job = { job_name: 'full_sync', mode: 'failure', last_attempt: new Date().toISOString(), last_attempt_ok: 0, last_error: (source + ': ' + detail).slice(0, 250) };
node.warn('Full Sync failed: ' + source + ': ' + detail);
return msg;

if (!msg.secrets) { node.warn('Full Sync: no secrets available to log this failure to InfluxDB (failed before secrets loaded).'); return null; }
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;
